import { GoPanic } from "@gotots/runtime/panic.js";
function unaddressableSetter() {
    return GoPanic.raiseRuntime("reflect: Value.Set using unaddressable value");
}
export function createRuntimeStructFieldBuilder(resolveStorage) {
    const propertyAddress = (address) => address === undefined
        ? {}
        : { address: (owner) => address(resolveStorage(owner)) };
    const valueProperty = (type, resolveAdapter, key, address) => {
        const adapter = resolveAdapter();
        return {
            type,
            settable: true,
            get: (owner) => new adapter(resolveStorage(owner)[key]),
            set: (owner, field) => {
                const admitted = adapter.$is(field)
                    ? field.$go$value
                    : GoPanic.raiseRuntime("reflect: Value.Set received a foreign interface box");
                resolveStorage(owner)[key] = admitted;
            },
            ...propertyAddress(address),
        };
    };
    const copyingValueProperty = (type, resolveAdapter, key, copy, address) => {
        const adapter = resolveAdapter();
        return {
            type,
            settable: true,
            get: (owner) => new adapter(resolveStorage(owner)[key]),
            set: (owner, field) => {
                const admitted = adapter.$is(field)
                    ? field.$go$value
                    : GoPanic.raiseRuntime("reflect: Value.Set received a foreign interface box");
                resolveStorage(owner)[key] = copy(admitted);
            },
            ...propertyAddress(address),
        };
    };
    const readonlyValueProperty = (type, resolveAdapter, key, address) => {
        const adapter = resolveAdapter();
        return {
            type,
            settable: false,
            get: (owner) => new adapter(resolveStorage(owner)[key]),
            set: unaddressableSetter,
            ...propertyAddress(address),
        };
    };
    const value = (type, resolveAdapter, get, set, address) => {
        const adapter = resolveAdapter();
        return {
            type,
            settable: true,
            get: (owner) => new adapter(get(owner)),
            set: (owner, field) => {
                const admitted = adapter.$is(field)
                    ? field.$go$value
                    : GoPanic.raiseRuntime("reflect: Value.Set received a foreign interface box");
                set(owner, admitted);
            },
            ...(address === undefined ? {} : { address }),
        };
    };
    const readonlyValue = (type, resolveAdapter, get, address) => {
        const adapter = resolveAdapter();
        return {
            type,
            settable: false,
            get: (owner) => new adapter(get(owner)),
            set: unaddressableSetter,
            ...(address === undefined ? {} : { address }),
        };
    };
    const interfaceValue = (type, admit, get, set, address) => ({
        type,
        settable: true,
        get,
        set: (owner, field) => {
            set(owner, admit(field));
        },
        ...(address === undefined ? {} : { address }),
    });
    const readonlyInterface = (type, get, address) => ({
        type,
        settable: false,
        get,
        set: unaddressableSetter,
        ...(address === undefined ? {} : { address }),
    });
    return {
        valueProperty,
        copyingValueProperty,
        readonlyValueProperty,
        value,
        readonlyValue,
        interfaceValue,
        readonlyInterface,
    };
}
export function createRuntimePointerElementBuilder() {
    const value = (type, resolveAdapter, get, set) => {
        const adapter = resolveAdapter();
        return {
            type,
            get: (pointer) => new adapter(get(pointer)),
            set: (pointer, field) => {
                const admitted = adapter.$is(field)
                    ? field.$go$value
                    : GoPanic.raiseRuntime("reflect: Value.Set received a foreign interface box");
                set(pointer, admitted);
            },
        };
    };
    const interfaceValue = (type, admit, get, set) => ({
        type,
        get,
        set: (pointer, field) => {
            set(pointer, admit(field));
        },
    });
    return { value, interfaceValue };
}
